#requires -Version 7.6
function Get-QuietResourceDocumentation {
    <#
    .SYNOPSIS
    Generates the resource inventory and dependency graph from the lock and inspected source references.
    .PARAMETER WorkspaceRoot
    Repository to document.
    #>
    param([string]$WorkspaceRoot)
    $module=Join-Path $WorkspaceRoot FrenchExDev2.QuietCli.Core.PoSh
    $manifest=Join-Path $module resources/dependencies.lock.json
    if(!(Test-Path $module)){return "# Resource inventory and source dependencies`n`nThis workspace declares no Core resource payloads.`n"}
    $lock=Get-Content $manifest -Raw -Encoding utf8|ConvertFrom-Json
    $lines=[Collections.Generic.List[string]]::new()
    foreach($line in @('# Resource inventory and source dependencies','','Generated by [Sync-ResourcesReadme.ps1](../../scripts/Sync-ResourcesReadme.ps1). This inventory describes declared bytes and inspected code; it does not require restored binaries or claim runtime qualification.','','## Ownership and lifecycle','','- Downloaded resources are ignored by Git, restored from pinned NuGet packages by Restore-CoreResources.ps1 and verified before use. dotnet restore restores project dependencies, not these module payloads.','- Ensure-QuietResource verifies, restores on demand through ShouldProcess, then loads a matching managed type when requested. Product module import never downloads dependencies.','- PTY resources are source-built by Build-PtyBridge.ps1 and validated by RuntimeTargets.ps1. They are never downloaded by Ensure.','- Agent instruction resources are staged by AgentDocuments.ps1 from docs/agents and verified by the agent-instruction companion tests.','- Packaging copies verified resource payloads; provenance/lock updates are explicit maintenance operations.','','~~~mermaid','flowchart TD','    L[dependencies.lock.json] --> E[Ensure-QuietResource]','    E --> V{Pinned bytes available?}','    V -- No --> R[Restore-CoreResources using local NuGet archive cache]','    R --> H[Verify exact resource hash]','    V -- Yes --> H','    H --> C[Automation or product consumer]','    S[native PTY source] --> B[Build-PtyBridge]','    B --> P[Tracked PTY resources]','    A[docs/agents] --> D[AgentDocuments staging]','    P --> K[Verified module packaging]','    D --> K','    C --> K','~~~','','## Declared payloads','','| Path under Core | Package | Version | Bytes | SHA-256 | Origin |','| --- | --- | --- | ---: | --- | --- |')){$lines.Add($line)}
    foreach($file in @($lock.Files|Sort-Object Path)){
        $package=@($lock.Packages|Where-Object Id -CEQ $file.Package)
        $origin=if($package.Count -eq 1){[string]$package[0].Source}else{'source receipt'}
        $lines.Add('| '+$file.Path+' | '+$file.Package+' | '+$file.Version+' | '+$file.Bytes+' | '+$file.SHA256+' | '+$origin+' |')
    }
    $lines.Add('');$lines.Add('## Direct source references');$lines.Add('')
    $lines.Add('References are extracted from PowerShell/C# source text. Dynamic module copies also transport resources: New-WorkspacePackage.ps1, Copy-QuietGalleryCoreModule in Gallery.ps1, and Invoke-ContainerWorker.ps1. The source hashes below make edits to readers/writers visible to this gate.')
    $lines.Add('');$lines.Add('| Source | Resource-related code | Source SHA-256 |');$lines.Add('| --- | --- | --- |')
    . (Join-Path $PSScriptRoot SourceIdentity.ps1)
    foreach($file in Get-QuietSourceFiles $WorkspaceRoot){
        if($file.Path -notmatch '\.(ps1|psm1|cs)$' -or $file.Path -match '\.Tests\.PoSh/|^scripts/ResourceDocumentation\.ps1$'){continue}
        $text=Get-Content (Join-Path $WorkspaceRoot $file.Path) -Raw -Encoding utf8
        $references=@([regex]::Matches($text,'(?im)^.*(?:resources[/\\]|["'']resources["'']|Restore-CoreResources|Ensure-QuietResource|Copy-QuietProductionAgentDocuments).*$')|ForEach-Object {$_.Value.Trim()}|Sort-Object -Unique)
        if(!$references.Count){continue}
        $description=($references|ForEach-Object {if($_.Length -gt 180){$_.Substring(0,180)+'…'}else{$_}}) -join '<br>'
        $description=[Net.WebUtility]::HtmlEncode($description).Replace('&lt;br&gt;','<br>').Replace('|','&#124;')
        $lines.Add('| '+$file.Path+' | '+$description+' | '+$file.SHA256+' |')
    }
    $lines.Add('');$lines.Add('## Scope and verification');$lines.Add('')
    $lines.Add('The generated source-reference graph is an inventory, not complete static data-flow analysis. Locks define exact files; dynamic copy edges are explicitly listed. Test-Resources.ps1 validates this inventory. Resource payload readiness is verified by Ensure-QuietResource and the existing runtime verifier, not by source-only documentation checks.')
    $lines.Add('');$lines.Add('[Resource contract](../../README-resources.md) · [CREDITS.md](../../CREDITS.md).')
    return (($lines -join "`n")+"`n")
}
